Step.SQLStatement:
DO $gw_apply$
DECLARE
  payload jsonb := '[]'::jsonb;
  part record;
  b jsonb;
  r jsonb;
  tab text;
  key_sql text;
  col_sql text;
  tcol_sql text;
  ecol_sql text;
  found_rows integer;
  matching boolean;
  existing_rows integer := 0;
  total_rows integer := 0;
  inserted_rows integer := 0;
  maximum_id numeric;
  id_column text;
  scenario record;
  product_id numeric;
  physical_qty numeric;
  movement_qty numeric;
  cost_qty numeric;
  unit_cost numeric;
  ledger_value numeric;
  imbalance_count integer;
BEGIN
  PERFORM pg_advisory_xact_lock(39400210355::bigint);
  PERFORM set_config('search_path','adempiere,public',true);

  IF (SELECT count(*) FROM adempiere.ad_migration
       WHERE btrim(name)='Add GardenWorld Average Invoice Costing Examples'
         AND seqno=10355 AND btrim(releaseno)='3.9.4.002' AND btrim(entitytype)='U') <> 1 THEN
    RAISE EXCEPTION 'Import this XML with the ADempiere migration importer; migration identity is missing or ambiguous';
  END IF;

  FOR part IN
    SELECT s.sqlstatement
      FROM adempiere.ad_migrationstep s
      JOIN adempiere.ad_migration m USING(ad_migration_id)
     WHERE btrim(m.name)='Add GardenWorld Average Invoice Costing Examples'
       AND m.seqno=10355 AND btrim(m.releaseno)='3.9.4.002' AND btrim(m.entitytype)='U'
       AND s.comments LIKE 'GW-AIC payload %'
     ORDER BY s.seqno
  LOOP
    payload := payload || split_part(part.sqlstatement,'$gw_seed$',2)::jsonb;
  END LOOP;
  IF jsonb_array_length(payload)=0 THEN RAISE EXCEPTION 'Missing GardenWorld fixture payload'; END IF;

  -- Validate all dependencies, complete schema and ID collisions BEFORE inserting anything.
  -- Existing rows are accepted only when every exported column is identical.
  FOR b IN SELECT value FROM jsonb_array_elements(payload)
  LOOP
    tab:=b->>'table';
    IF tab !~ '^[a-z][a-z0-9_]*$' OR to_regclass('adempiere.'||tab) IS NULL THEN
      RAISE EXCEPTION 'Missing or invalid required table: %',tab;
    END IF;
    IF EXISTS (SELECT 1 FROM jsonb_array_elements_text(b->'columns') c(col)
               WHERE col !~ '^[a-z][a-z0-9_]*$'
                  OR NOT EXISTS (SELECT 1 FROM information_schema.columns a
                                  WHERE a.table_schema='adempiere' AND a.table_name=tab AND a.column_name=col)) THEN
      RAISE EXCEPTION 'Schema mismatch in %. Apply the prerequisite local XML migrations first',tab;
    END IF;
    SELECT string_agg(format('t.%1$I IS NOT DISTINCT FROM e.%1$I',value),' AND ')
      INTO key_sql FROM jsonb_array_elements_text(b->'keys');
    SELECT string_agg(format('t.%I',value),','),string_agg(format('e.%I',value),',')
      INTO tcol_sql,ecol_sql FROM jsonb_array_elements_text(b->'columns');
    FOR r IN SELECT value FROM jsonb_array_elements(b->'rows')
    LOOP
      EXECUTE format('SELECT count(*),coalesce(bool_and(ROW(%s) IS NOT DISTINCT FROM ROW(%s)),false)
                        FROM adempiere.%I t CROSS JOIN jsonb_populate_record(NULL::adempiere.%I,$1) e
                       WHERE %s',tcol_sql,ecol_sql,tab,tab,key_sql)
        INTO found_rows,matching USING r;
      IF b->>'kind'='reference' THEN
        IF found_rows<>1 OR NOT matching THEN
          RAISE EXCEPTION 'Shared GardenWorld reference differs in %: %. No fixture data inserted',tab,r;
        END IF;
      ELSE
        total_rows:=total_rows+1;
        IF found_rows>1 OR (found_rows=1 AND NOT matching) THEN
          RAISE EXCEPTION 'ID collision or changed existing fixture in %. No existing rows will be overwritten. Key columns: %',tab,b->'keys';
        END IF;
        existing_rows:=existing_rows+found_rows;
      END IF;
    END LOOP;
  END LOOP;
  IF total_rows<>323 THEN RAISE EXCEPTION 'Incomplete fixture payload: expected 323 rows, got %',total_rows; END IF;
  IF existing_rows NOT IN (0,total_rows) THEN
    RAISE EXCEPTION 'Partial fixture already exists (% of % rows). Use a clean seed copy or reconcile it first',existing_rows,total_rows;
  END IF;

  -- A single material element is shared by Standard and Average Invoice cost types.
  -- Never disable a material element that already has valuation data.
  IF EXISTS(SELECT 1 FROM adempiere.m_cost WHERE m_costelement_id=1000000)
     OR EXISTS(SELECT 1 FROM adempiere.m_costdetail WHERE m_costelement_id=1000000)
     OR EXISTS(SELECT 1 FROM adempiere.m_costqueue WHERE m_costelement_id=1000000) THEN
    RAISE EXCEPTION 'Material element 1000000 has valuation data; review its use before this migration';
  END IF;
  IF EXISTS (SELECT 1 FROM adempiere.m_costelement WHERE m_costelement_id=100
             AND (ad_client_id<>11 OR costelementtype<>'M' OR isdefault<>'Y'
                  OR isactive<>'Y' OR costingmethod NOT IN ('S'))) THEN
    RAISE EXCEPTION 'Unexpected default Material configuration';
  END IF;
  UPDATE adempiere.m_costelement SET isactive='N',updated=now(),updatedby=100
   WHERE m_costelement_id=1000000 AND ad_client_id=11 AND costelementtype='M' AND isdefault='N' AND isactive='Y';
  UPDATE adempiere.m_costelement SET costingmethod=NULL,updated=now(),updatedby=100
   WHERE m_costelement_id=100 AND ad_client_id=11 AND costelementtype='M' AND isdefault='Y' AND costingmethod='S';
  IF (SELECT count(*) FROM adempiere.m_costelement WHERE ad_client_id=11 AND costelementtype='M' AND isactive='Y')<>1 THEN
    RAISE EXCEPTION 'Expected one active GardenWorld Material element';
  END IF;

  IF existing_rows=0 THEN
    FOR b IN SELECT value FROM jsonb_array_elements(payload)
    LOOP
      IF b->>'kind'<>'data' THEN CONTINUE; END IF;
      tab:=b->>'table';
      SELECT string_agg(format('%I',value),','),string_agg(format('e.%I',value),',')
        INTO col_sql,ecol_sql FROM jsonb_array_elements_text(b->'columns');
      EXECUTE format('INSERT INTO adempiere.%I (%s)
                      SELECT %s FROM jsonb_populate_recordset(NULL::adempiere.%I,$1) e',
                      tab,col_sql,ecol_sql,tab) USING b->'rows';
      GET DIAGNOSTICS found_rows=ROW_COUNT;
      inserted_rows:=inserted_rows+found_rows;
    END LOOP;
    IF inserted_rows<>total_rows THEN RAISE EXCEPTION 'Fixture insert count mismatch'; END IF;
  END IF;

  -- Validate the final stock, cost dimension, movement totals and inventory ledger.
  FOR scenario IN
    SELECT * FROM (VALUES
      ('GW-AIC-READY',10::numeric,10::numeric,100::numeric),
      ('GW-AIC-AVG',16::numeric,15::numeric,240::numeric),
      ('GW-AIC-INVOICE',10::numeric,12::numeric,120::numeric),
      ('GW-AIC-NEG',5::numeric,20::numeric,100::numeric)
    ) e(code,qty,price,inventory_value)
  LOOP
    SELECT m_product_id INTO STRICT product_id FROM adempiere.m_product
     WHERE ad_client_id=11 AND value=scenario.code;
    SELECT sum(qtyonhand) INTO physical_qty FROM adempiere.m_storage WHERE m_product_id=product_id;
    SELECT sum(movementqty) INTO movement_qty FROM adempiere.m_transaction WHERE m_product_id=product_id;
    SELECT currentqty,currentcostprice INTO STRICT cost_qty,unit_cost FROM adempiere.m_cost
     WHERE ad_client_id=11 AND m_product_id=product_id AND c_acctschema_id=101
       AND m_costtype_id=50000 AND m_costelement_id=100 AND ad_org_id=0
       AND coalesce(m_warehouse_id,0)=0 AND m_attributesetinstance_id=0;
    SELECT sum(f.amtacctdr-f.amtacctcr) INTO ledger_value FROM adempiere.fact_acct f
     WHERE f.m_product_id=product_id AND f.c_acctschema_id=101
       AND f.account_id=(SELECT v.account_id FROM adempiere.m_product_acct a
                         JOIN adempiere.c_validcombination v ON v.c_validcombination_id=a.p_asset_acct
                        WHERE a.m_product_id=product_id AND a.c_acctschema_id=101);
    IF physical_qty IS DISTINCT FROM scenario.qty OR movement_qty IS DISTINCT FROM scenario.qty
       OR cost_qty IS DISTINCT FROM scenario.qty OR unit_cost IS DISTINCT FROM scenario.price
       OR ledger_value IS DISTINCT FROM scenario.inventory_value THEN
      RAISE EXCEPTION 'Stock/cost/ledger validation failed for %',scenario.code;
    END IF;
    IF NOT EXISTS(SELECT 1 FROM adempiere.m_costdetail WHERE m_product_id=product_id AND m_costtype_id=50000) THEN
      RAISE EXCEPTION 'Missing cost history for %',scenario.code;
    END IF;
  END LOOP;
  SELECT count(*) INTO imbalance_count FROM (
    SELECT f.ad_table_id,f.record_id FROM adempiere.fact_acct f
     WHERE (f.ad_table_id,f.record_id) IN (
       SELECT f2.ad_table_id,f2.record_id FROM adempiere.fact_acct f2
       JOIN adempiere.m_product p ON p.m_product_id=f2.m_product_id
       WHERE p.ad_client_id=11 AND p.value IN('GW-AIC-READY','GW-AIC-AVG','GW-AIC-INVOICE','GW-AIC-NEG'))
     GROUP BY f.ad_table_id,f.record_id HAVING sum(f.amtacctdr-f.amtacctcr)<>0
  ) unbalanced;
  IF imbalance_count<>0 THEN RAISE EXCEPTION 'Unbalanced fixture journals'; END IF;
  IF (SELECT min(balance) FROM (
        SELECT sum(t.movementqty) OVER(ORDER BY t.movementdate,t.m_transaction_id) AS balance
          FROM adempiere.m_transaction t JOIN adempiere.m_product p USING(m_product_id)
         WHERE p.ad_client_id=11 AND p.value='GW-AIC-NEG') h)<>-5 THEN
    RAISE EXCEPTION 'Expected historical negative-stock scenario is missing';
  END IF;

  -- Keep ADempiere's ID allocators ahead of all imported identifiers; never decrease them.
  FOR b IN SELECT value FROM jsonb_array_elements(payload)
  LOOP
    IF b->>'kind'<>'data' THEN CONTINUE; END IF;
    tab:=b->>'table';id_column:=tab||'_id';
    IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements_text(b->'columns') c(col) WHERE col=id_column) THEN CONTINUE; END IF;
    EXECUTE format('SELECT max(%I) FROM adempiere.%I',id_column,tab) INTO maximum_id;
    UPDATE adempiere.ad_sequence SET currentnext=greatest(currentnext,maximum_id+incrementno)
     WHERE lower(name)=tab AND istableid='Y' AND currentnext<=maximum_id;
  END LOOP;
  RAISE NOTICE 'GardenWorld Average Invoice examples: % rows inserted, % identical rows retained. Stock, costs and journals verified.',inserted_rows,existing_rows;
END $gw_apply$;
